func TestRemediationPerStalledPhase(t *testing.T) {
	cases := map[Phase]Remediation{
		Detaching:  RemediationForceDetach,
		Creating:   RemediationOperator,
		Formatting: RemediationOperator,
		Resizing:   RemediationOperator,
