var t0 = time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)

func mustApply(t *testing.T, state State, event Event, at time.Time) State {
	t.Helper()
	next, err := Apply(state, event, at, "")
	if err != nil {
		t.Fatalf("Apply(%s, %s): %v", state.Phase, event, err)
	}
	return next
}

func (phase Phase) Valid() bool {
	switch phase {
	case Pending, Creating, Available, Attaching, Attached, Formatting, Mounted,
		Resizing, Detaching, Detached, Deleting, Deleted, Stuck, Held:
		return true
	default:
		return false
	}
}

// Transitional reports whether phase waits on an external effect and is
// therefore bounded by a deadline.
func (phase Phase) Transitional() bool {
	switch phase {
	case Creating, Attaching, Formatting, Resizing, Detaching, Deleting:
		return true
	default:
		return false
	}
}

func New(now time.Time) State {
	return State{Phase: Pending, Since: now.UTC()}
}

// Apply returns the state after event at now. It never mutates its input and
// rejects any transition not listed in the transition table.
func Apply(state State, event Event, now time.Time, reason string) (State, error) {
	if !state.Phase.Valid() {
		return state, fmt.Errorf("%w: unknown phase %q", ErrInvalidTransition, state.Phase)
	}
	now = now.UTC()
	if state.Phase == Deleted {
		return state, ErrTerminal
	}
	switch event {
	case EventHold:
		if state.Phase == Held {
			return state, nil
		}
		from := state.Phase
		if from == Stuck {
			from = state.StuckFrom
		}
		return State{Phase: Held, Since: now, HeldFrom: from, Reason: reason, Attempts: state.Attempts}, nil
	case EventRelease:
		if state.Phase != Held || !state.HeldFrom.Valid() || state.HeldFrom == Held || state.HeldFrom == Stuck {
			return state, fmt.Errorf("%w: release requires a held volume with a recorded phase", ErrInvalidTransition)
		}
		// Attempts survive the hold: a release must not reset the bound that
		// escalates repeated same-host attach stalls to host replacement.
		return State{Phase: state.HeldFrom, Since: now, Attempts: state.Attempts}, nil
	case EventRetry:
		if state.Phase != Stuck || !state.StuckFrom.Transitional() {
			return state, fmt.Errorf("%w: retry requires a stuck transitional phase", ErrInvalidTransition)
		}
		return State{Phase: state.StuckFrom, Since: now, Attempts: state.Attempts + 1}, nil
	}
	from := state.Phase
	if from == Stuck {
		// A late positive observation resolves a stall without a retry.
		from = state.StuckFrom
	}
	next, ok := transitions[edge{from, event}]
	if !ok || state.Phase == Held {
		return state, fmt.Errorf("%w: %s on %s", ErrInvalidTransition, event, state.Phase)
	}
	if next == from {
		// Re-observing or re-requesting the current phase keeps the original
		// deadline; a stuck volume stays stuck until it makes progress or an
		// explicit retry restarts its deadline.
		return state, nil
	}
	attempts := uint32(0)
	if attachRetryCycle(from) && attachRetryCycle(next) {
		// A force-detach-retry passes through Detaching and Detached back
		// to Attaching. The same-host attach retry count must survive that
		// cycle, or repeated stalls never escalate to host replacement. It
		// resets once the attach succeeds or the volume leaves the cycle.
		attempts = state.Attempts
	}
	return State{Phase: next, Since: now, Attempts: attempts}, nil
}

// attachRetryCycle reports the phases a same-host attach retry cycles through.
func attachRetryCycle(phase Phase) bool {
	return phase == Attaching || phase == Detaching || phase == Detached
}

type edge struct {
	from  Phase
	event Event
}

// transitions is the complete allowed graph outside Hold/Release/Retry.
// Re-requesting the current transitional phase is idempotent.
var transitions = map[edge]Phase{
	{Pending, EventCreateRequested}:   Creating,
	{Creating, EventCreateRequested}:  Creating,
	{Creating, EventCreated}:          Available,
	{Creating, EventDeleteRequested}:  Deleting,
	{Available, EventCreated}:         Available,
	{Available, EventAttachRequested}: Attaching,
	{Available, EventDeleteRequested}: Deleting,
	{Attaching, EventAttachRequested}: Attaching,
	{Attaching, EventAttached}:        Attached,
	{Attaching, EventDetachRequested}: Detaching,
	{Attaching, EventDetached}:        Detached,
	{Attached, EventAttached}:         Attached,
	{Attached, EventFormatStarted}:    Formatting,
	{Attached, EventMounted}:          Mounted,
	{Attached, EventDetachRequested}:  Detaching,
	{Attached, EventDetached}:         Detached,
	{Formatting, EventAttached}:       Formatting,
	{Formatting, EventFormatStarted}:  Formatting,
	{Formatting, EventMounted}:        Mounted,
	{Mounted, EventAttached}:          Mounted,
	{Mounted, EventMounted}:           Mounted,
	{Mounted, EventResizeRequested}:   Resizing,
	{Mounted, EventDetachRequested}:   Detaching,
	{Mounted, EventDetached}:          Detached,
	{Resizing, EventAttached}:         Resizing,
	{Resizing, EventMounted}:          Resizing,
	{Resizing, EventResizeRequested}:  Resizing,
	{Resizing, EventResized}:          Mounted,
	{Detaching, EventDetachRequested}: Detaching,
	{Detaching, EventDetached}:        Detached,
	{Detached, EventDetached}:         Detached,
	{Detached, EventAttachRequested}:  Attaching,
	{Detached, EventDeleteRequested}:  Deleting,
	{Deleting, EventDeleteRequested}:  Deleting,
	{Deleting, EventDeleted}:          Deleted,
}

// FromOCIAttachmentState maps an OCI volume-attachment lifecycle state to the
// event it represents. Unknown states return false and must be held.
func FromOCIAttachmentState(state string) (Event, bool) {
	switch state {
	case "ATTACHING":
		return EventAttachRequested, true
	case "ATTACHED":
		return EventAttached, true
	case "DETACHING":
		return EventDetachRequested, true
	case "DETACHED":
		return EventDetached, true
	default:
		return "", false
	}
}

// Deadlines bound every transitional phase. Zero fields use the defaults.
type Deadlines struct {
	Creating   time.Duration `json:"creating,omitzero"`
	Attaching  time.Duration `json:"attaching,omitzero"`
	Formatting time.Duration `json:"formatting,omitzero"`
	Resizing   time.Duration `json:"resizing,omitzero"`
	Detaching  time.Duration `json:"detaching,omitzero"`
	Deleting   time.Duration `json:"deleting,omitzero"`
	// MaxAttachRetries bounds same-host attach retries before the remediation
	// escalates to host replacement.
	MaxAttachRetries uint32 `json:"max_attach_retries,omitzero"`
}

// DefaultDeadlines are conservative OCI service-level bounds: an OCI
// paravirtualized attach normally settles in well under two minutes, so ten
// minutes in ATTACHING is a real stall rather than a slow API.
func DefaultDeadlines() Deadlines {
	return Deadlines{
		Creating:         15 * time.Minute,
		Attaching:        10 * time.Minute,
		Formatting:       30 * time.Minute,
		Resizing:         30 * time.Minute,
		Detaching:        10 * time.Minute,
		Deleting:         30 * time.Minute,
		MaxAttachRetries: 2,
	}
}

const maxDeadline = 24 * time.Hour

// WithDefaults fills zero fields from DefaultDeadlines.
func (deadlines Deadlines) WithDefaults() Deadlines {
	defaults := DefaultDeadlines()
	fill := func(value *time.Duration, fallback time.Duration) {
		if *value == 0 {
			*value = fallback
		}
	}
	fill(&deadlines.Creating, defaults.Creating)
	fill(&deadlines.Attaching, defaults.Attaching)
	fill(&deadlines.Formatting, defaults.Formatting)
	fill(&deadlines.Resizing, defaults.Resizing)
	fill(&deadlines.Detaching, defaults.Detaching)
	fill(&deadlines.Deleting, defaults.Deleting)
	if deadlines.MaxAttachRetries == 0 {
		deadlines.MaxAttachRetries = defaults.MaxAttachRetries
	}
	return deadlines
}

// Validate rejects negative or unbounded deadlines.
func (deadlines Deadlines) Validate() error {
	for _, value := range []time.Duration{
		deadlines.Creating, deadlines.Attaching, deadlines.Formatting,
		deadlines.Resizing, deadlines.Detaching, deadlines.Deleting,
	} {
		if value < 0 || value > maxDeadline {
			return errors.New("retained volume lifecycle deadlines must be between zero and 24h")
		}
	}
	if deadlines.MaxAttachRetries > 10 {
		return errors.New("retained volume attach retries must not exceed 10")
	}
	return nil
}

// For returns the deadline of phase, or zero for non-transitional phases.
func (deadlines Deadlines) For(phase Phase) time.Duration {
	deadlines = deadlines.WithDefaults()
	switch phase {
	case Creating:
		return deadlines.Creating
	case Attaching:
		return deadlines.Attaching
	case Formatting:
		return deadlines.Formatting
	case Resizing:
		return deadlines.Resizing
	case Detaching:
		return deadlines.Detaching
	case Deleting:
		return deadlines.Deleting
	default:
		return 0
	}
}

// Expired reports whether a transitional state has outlived its deadline. A
// zero Since or a Since in the future is treated as expired so a corrupt or
// clock-skewed record cannot wait forever.
func (deadlines Deadlines) Expired(state State, now time.Time) bool {
	limit := deadlines.For(state.Phase)
	if limit == 0 {
		return false
	}
	if state.Since.IsZero() || state.Since.After(now.Add(time.Minute)) {
		return true
	}
	return now.Sub(state.Since) >= limit
}

// Check moves an expired transitional state to Stuck. It returns the state
// unchanged and false otherwise.
func Check(state State, now time.Time, deadlines Deadlines) (State, bool) {
	if !state.Phase.Transitional() || !deadlines.Expired(state, now) {
		return state, false
	}
	return State{
		Phase: Stuck, Since: now.UTC(), StuckFrom: state.Phase, Attempts: state.Attempts,
		Reason: fmt.Sprintf("%s exceeded %s", state.Phase, deadlines.For(state.Phase)),
	}, true
}

// Remediation is the next safe action for a stuck volume. Every remediation
// that moves data access requires its own fencing proof at execution time;
// this decision never authorizes an effect by itself.
type Remediation string

const (
	RemediationNone Remediation = ""
	// RemediationForceDetachRetry force-detaches the stalled attachment (no
	// writer has ever been granted a mount through it) and retries the attach
	// on the same host with a fresh idempotency key.
	RemediationForceDetachRetry Remediation = "force-detach-retry"
	// RemediationReplaceHost gives up on the host: the volume is reattached to
	// a replacement only after the old instance is proven terminated.
	RemediationReplaceHost Remediation = "replace-host"
	// RemediationForceDetach repeats a stalled detach with force semantics.
	RemediationForceDetach Remediation = "force-detach"
	// RemediationOperator holds for an exact-resource operator workflow.
	RemediationOperator Remediation = "operator"
)

// Remediate chooses the remediation for a stuck state.
func Remediate(state State, deadlines Deadlines) Remediation {
	if state.Phase != Stuck {
		return RemediationNone
	}
	deadlines = deadlines.WithDefaults()
	switch state.StuckFrom {
	case Attaching:
		if state.Attempts < deadlines.MaxAttachRetries {
			return RemediationForceDetachRetry
		}
		return RemediationReplaceHost
	case Detaching:
		return RemediationForceDetach
	default:
		// Create, format, resize and delete stalls touch durable data or an
		// unknown provider outcome; automation never guesses.
		return RemediationOperator
	}
}

